struct LoginBloc {
    std::variant<Idle, Busy, Failed> state{Idle{}};
    std::vector<std::function<void(const std::variant<Idle, Busy, Failed>&)>> subs;

    void dispatch(const Event& ev) {
        auto next = reduce(state, ev);            // pure (state, event) -> state
        if (next == state) return;                // conflate equal states
        state = std::move(next);
        auto snapshot = subs;                     // copy: callbacks may unsubscribe
        for (auto& fn : snapshot) fn(state);
    }
};
